import{c as e,i as t,n,o as r,r as i,s as a,t as o}from"./app-BFCn-tw0.js";var s=JSON.parse(`{"path":"/web3/bc/calg/poet.html","title":"POET","lang":"zh-CN","frontmatter":{"description":"POET 什么是经过时间证明 (Proof of Elapsed Time, POET) 经过时间证明是一种区块链共识机制，旨在通过测量节点在区块生成过程中经过的时间来实现共识。POET 特别适用于需要低功耗和高效能的分布式网络，通常用于物联网（IoT）和轻量级区块链应用。 工作原理 时间证明生成： 节点请求并获取一个可信任的随机数生成器（如 Inte...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"POET\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/bc/calg/poet.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"POET"}],["meta",{"property":"og:description","content":"POET 什么是经过时间证明 (Proof of Elapsed Time, POET) 经过时间证明是一种区块链共识机制，旨在通过测量节点在区块生成过程中经过的时间来实现共识。POET 特别适用于需要低功耗和高效能的分布式网络，通常用于物联网（IoT）和轻量级区块链应用。 工作原理 时间证明生成： 节点请求并获取一个可信任的随机数生成器（如 Inte..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":2.06,"words":618},"filePathRelative":"web3/bc/calg/poet.md","autoDesc":true}`),c={name:`poet.md`};function l(o,s,c,l,u,d){let f=e(`DocsAD`);return a(),i(`div`,null,[s[0]||=n(`h1`,{id:`poet`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#poet`},[n(`span`,null,`POET`)])],-1),s[1]||=n(`h2`,{id:`什么是经过时间证明-proof-of-elapsed-time-poet`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#什么是经过时间证明-proof-of-elapsed-time-poet`},[n(`span`,null,`什么是经过时间证明 (Proof of Elapsed Time, POET)`)])],-1),s[2]||=n(`p`,null,`经过时间证明是一种区块链共识机制，旨在通过测量节点在区块生成过程中经过的时间来实现共识。POET 特别适用于需要低功耗和高效能的分布式网络，通常用于物联网（IoT）和轻量级区块链应用。`,-1),r(f),s[3]||=t(`<h2 id="工作原理" tabindex="-1"><a class="header-anchor" href="#工作原理"><span>工作原理</span></a></h2><ol><li><p><strong>时间证明生成</strong>：</p><ul><li>节点请求并获取一个可信任的随机数生成器（如 Intel SGX）的访问权限。生成的随机数用于确定节点生成区块的时间。</li></ul></li><li><p><strong>随机选择</strong>：</p><ul><li>节点根据生成的随机数，计算出一个时间段（例如 0 到 X 毫秒）。节点在该时间段内等待生成新区块的机会。</li></ul></li><li><p><strong>区块生成</strong>：</p><ul><li>一旦节点的等待时间到达，节点便可以生成新区块并将其广播到网络中。其他节点会验证该区块的有效性。</li></ul></li><li><p><strong>奖励分配</strong>：</p><ul><li>成功生成区块的节点会获得区块奖励，激励节点参与网络共识。</li></ul></li></ol><h2 id="优点" tabindex="-1"><a class="header-anchor" href="#优点"><span>优点</span></a></h2><ul><li><strong>低能耗</strong>：POET 相较于传统的挖矿机制，能耗较低，因为节点不需要进行大量的计算。</li><li><strong>快速确认</strong>：由于使用随机选择和时间段等待，能够在较短的时间内达成共识，提高交易处理效率。</li><li><strong>公平性</strong>：通过随机选择生成区块的节点，减少了中心化的风险，确保每个参与者都有机会。</li></ul><h2 id="缺点" tabindex="-1"><a class="header-anchor" href="#缺点"><span>缺点</span></a></h2><ul><li><strong>信任问题</strong>：POET 依赖于可信的硬件或时间服务，如果这些服务被攻击或受到影响，可能会影响整个网络的安全性。</li><li><strong>安全性挑战</strong>：攻击者可能尝试操纵随机数生成过程，从而影响区块生成的公平性。</li><li><strong>实现复杂性</strong>：部署和维护 POET 机制可能需要复杂的硬件支持和管理。</li></ul><h2 id="应用实例" tabindex="-1"><a class="header-anchor" href="#应用实例"><span>应用实例</span></a></h2><ul><li><strong>Hyperledger Sawtooth</strong>：使用 POET 作为共识机制之一，适用于需要低功耗和高效率的企业级区块链应用。</li></ul><h2 id="结论" tabindex="-1"><a class="header-anchor" href="#结论"><span>结论</span></a></h2><p>经过时间证明作为一种创新的共识机制，通过随机选择和时间段等待来实现共识，提供了一种低能耗、高效率的解决方案。尽管面临信任和安全性挑战，POET 在轻量级区块链应用中展现了良好的潜力。</p>`,10)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};